import React, { useState, useEffect } from 'react';

const COLORS = {
  bg: '#050505',
  card: '#111111',
  accent: '#3b82f6', // Azul Neon
  gold: '#fbbf24',
  text: '#ffffff',
  muted: '#94a3b8',
  border: '#1e293b'
};

export default function App() {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [processos, setProcessos] = useState(() => {
    const salvo = localStorage.getItem('juris_data');
    return salvo ? JSON.parse(salvo) : [];
  });

  useEffect(() => {
    localStorage.setItem('juris_data', JSON.stringify(processos));
  }, [processos]);

  const faturamentoTotal = processos.reduce((acc, curr) => acc + Number(curr.valor || 0), 0);

  return (
    <div style={s.app}>
      {/* SIDEBAR LATERAL ESTILO SAAS */}
      <aside style={s.sidebar}>
        <div style={s.brand}>
          <div style={s.brandIcon}>J</div>
          <span>JurisPRO</span>
        </div>
        
        <nav style={s.nav}>
          <NavItem icon="📊" label="Dashboard" active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} />
          <NavItem icon="📂" label="Processos" active={activeTab === 'processos'} onClick={() => setActiveTab('processos')} />
          <NavItem icon="💳" label="Financeiro" active={activeTab === 'financeiro'} onClick={() => setActiveTab('financeiro')} />
          <NavItem icon="⚙️" label="Configurações" active={activeTab === 'config'} onClick={() => setActiveTab('config')} />
        </nav>

        <div style={s.userProfile}>
          <div style={s.avatar}>DR</div>
          <div>
            <div style={{fontSize: '14px', fontWeight: '600'}}>Dr. Rodrigo</div>
            <div style={{fontSize: '11px', color: COLORS.muted}}>Plano Premium</div>
          </div>
        </div>
      </aside>

      {/* ÁREA DE CONTEÚDO */}
      <main style={s.content}>
        <header style={s.header}>
          <h2 style={{margin: 0}}>Painel de Controle</h2>
          <div style={s.dateBadge}>{new Date().toLocaleDateString('pt-BR', { dateStyle: 'full' })}</div>
        </header>

        {activeTab === 'dashboard' && (
          <div style={s.dashboardGrid}>
            {/* CARDS DE RESUMO */}
            <StatCard label="Receita Estimada" value={`R$ ${faturamentoTotal.toLocaleString()}`} color={COLORS.accent} />
            <StatCard label="Processos Ativos" value={processos.length} color={COLORS.gold} />
            <StatCard label="Prazos p/ Hoje" value="04" color="#ef4444" />

            {/* BENTO BOX - GRÁFICO E LISTA */}
            <div style={{...s.card, gridColumn: 'span 2', height: '300px'}}>
              <h4 style={s.cardTitle}>Desempenho Mensal</h4>
              <div style={s.chartSim}>
                {[40, 70, 45, 90, 65, 80, 95].map((h, i) => (
                  <div key={i} style={{...s.bar, height: `${h}%`}}></div>
                ))}
              </div>
            </div>

            <div style={s.card}>
              <h4 style={s.cardTitle}>Ações Rápidas</h4>
              <button style={s.actionBtn}>⚖️ Consultar PJe</button>
              <button style={s.actionBtn}>📝 Gerar Procuração</button>
              <button style={s.actionBtn}>📅 Agendar Reunião</button>
            </div>
          </div>
        )}

        {activeTab === 'processos' && (
          <div style={s.card}>
            <h4 style={s.cardTitle}>Gerenciamento de Casos</h4>
            <p style={{color: COLORS.muted}}>Visualize e edite sua carteira de clientes ativos.</p>
            <div style={s.tablePlaceholder}>
              {processos.length === 0 ? "Nenhum processo cadastrado ainda." : "Tabela de processos carregada."}
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

// COMPONENTES INTERNOS
const NavItem = ({icon, label, active, onClick}) => (
  <div onClick={onClick} style={s.navLink(active)}>
    <span style={{fontSize: '18px'}}>{icon}</span>
    {label}
  </div>
);

const StatCard = ({label, value, color}) => (
  <div style={s.statCard}>
    <span style={{color: COLORS.muted, fontSize: '13px'}}>{label}</span>
    <div style={{fontSize: '28px', fontWeight: 'bold', color: color, margin: '10px 0'}}>{value}</div>
    <div style={{fontSize: '11px', color: COLORS.success}}>+ 12% em relação ao mês anterior</div>
  </div>
);

// ESTILOS (SISTEMA DE DESIGN)
const s = {
  app: { display: 'flex', minHeight: '100vh', backgroundColor: COLORS.bg, color: COLORS.text, fontFamily: "'Inter', sans-serif" },
  sidebar: { width: '260px', backgroundColor: COLORS.card, borderRight: `1px solid ${COLORS.border}`, display: 'flex', flexDirection: 'column', padding: '20px' },
  brand: { display: 'flex', alignItems: 'center', gap: '12px', fontSize: '20px', fontWeight: 'bold', color: COLORS.accent, marginBottom: '40px', padding: '0 10px' },
  brandIcon: { width: '35px', height: '35px', backgroundColor: COLORS.accent, color: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center', borderRadius: '8px' },
  nav: { flex: 1 },
  navLink: (active) => ({
    display: 'flex', alignItems: 'center', gap: '15px', padding: '12px 15px', borderRadius: '10px', cursor: 'pointer', marginBottom: '5px',
    backgroundColor: active ? 'rgba(59, 130, 246, 0.1)' : 'transparent',
    color: active ? COLORS.accent : COLORS.muted,
    transition: '0.2s', fontWeight: active ? '600' : '400'
  }),
  userProfile: { display: 'flex', alignItems: 'center', gap: '12px', padding: '15px', borderTop: `1px solid ${COLORS.border}`, marginTop: '20px' },
  avatar: { width: '40px', height: '40px', borderRadius: '50%', backgroundColor: '#333', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '12px', fontWeight: 'bold' },
  content: { flex: 1, padding: '40px', overflowY: 'auto' },
  header: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '40px' },
  dateBadge: { padding: '8px 16px', backgroundColor: COLORS.card, borderRadius: '20px', fontSize: '12px', border: `1px solid ${COLORS.border}`, color: COLORS.muted },
  dashboardGrid: { display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px' },
  statCard: { backgroundColor: COLORS.card, padding: '25px', borderRadius: '16px', border: `1px solid ${COLORS.border}` },
  card: { backgroundColor: COLORS.card, padding: '25px', borderRadius: '16px', border: `1px solid ${COLORS.border}` },
  cardTitle: { margin: '0 0 20px 0', fontSize: '16px', fontWeight: '600' },
  chartSim: { display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', height: '180px', padding: '10px 0' },
  bar: { width: '30px', backgroundColor: COLORS.accent, borderRadius: '4px 4px 0 0', opacity: 0.7 },
  actionBtn: { width: '100%', padding: '12px', backgroundColor: COLORS.bg, border: `1px solid ${COLORS.border}`, color: 'white', borderRadius: '8px', marginBottom: '10px', textAlign: 'left', cursor: 'pointer', transition: '0.2s' },
  tablePlaceholder: { marginTop: '20px', padding: '40px', textAlign: 'center', border: `2px dashed ${COLORS.border}`, borderRadius: '12px', color: COLORS.muted }
};
